    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }
}

/* ============================================
   FOCUS VISIBLE STATE
   ============================================ */

button:focus-visible,
a:focus-visible,
input:focus-visible {
    outline: 2px solid var(--color-secondary);
    outline-offset: 2px;
}
