/* ============================================
   CSS CUSTOM PROPERTIES & UTILITIES
   ============================================ */

:root {
    --color-primary: #2c3e50;
    --color-secondary: #e74c3c;
    --color-accent: #d4a574;
    --color-background: #fafaf8;
    --color-surface: #ffffff;
    --color-text: #2c3e50;
    --color-text-light: #7f8c8d;
    --color-border: #ecf0f1;
    --color-success: #27ae60;

    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 4rem;

    --font-family-main: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    --font-size-base: 1rem;
    --font-size-lg: 1.125rem;
    --font-size-xl: 1.5rem;
    --font-size-2xl: 2rem;
    --font-size-3xl: 2.5rem;

    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.1);

    --radius-sm: 0.375rem;
    --radius-md: 0.5rem;
    --radius-lg: 1rem;

    --transition-fast: 150ms ease-in-out;
    --transition-normal: 300ms ease-in-out;
}

/* ============================================
   RESET & BASE STYLES
   ============================================ */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-family-main);
    font-size: var(--font-size-base);
    line-height: 1.6;
    color: var(--color-text);
    background-color: var(--color-background);
}

/* ============================================
   ACCESSIBILITY
   ============================================ */

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background-color: var(--color-primary);
    color: var(--color-surface);
    padding: var(--spacing-sm);
    text-decoration: none;
    z-index: 100;
}

.skip-link:focus {
    top: 0;
}

/* Remove focus styles only with keyboard navigation (modern approach) */
@media (prefers-reduced-motion: no-preference) {
    * {
        scroll-behavior: smooth;
    }
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* ============================================
   TYPOGRAPHY
   ============================================ */

h1 {
    font-size: var(--font-size-3xl);
    font-weight: 700;
    line-height: 1.2;
    margin-bottom: var(--spacing-md);
}

h2 {
    font-size: var(--font-size-2xl);
    font-weight: 700;
    line-height: 1.3;
    margin-bottom: var(--spacing-md);
}

h3 {
    font-size: var(--font-size-xl);
    font-weight: 600;
    line-height: 1.4;
}

p {
    margin-bottom: var(--spacing-md);
}

a {
    color: var(--color-secondary);
    text-decoration: none;
    transition: color var(--transition-fast);
}

a:hover {
    color: var(--color-primary);
    text-decoration: underline;
}

a:focus {
    outline: 2px solid var(--color-secondary);
    outline-offset: 2px;
}

/* ============================================
   LAYOUT
   ============================================ */

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

header {
    background-color: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 50;
    box-shadow: var(--shadow-sm);
}

.header-top {
    padding: var(--spacing-md) 0;
}

.header-top .container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
}

.logo {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: var(--color-primary);
    text-decoration: none;
    flex-shrink: 0;
}

.logo-icon {
    width: 32px;
    height: 32px;
    color: var(--color-accent);
}

.logo-text {
    display: none;
}

@media (min-width: 640px) {
    .logo-text {
        display: inline;
    }
}

/* ============================================
   NAVIGATION
   ============================================ */

.main-nav {
    flex: 1;
    min-width: 0;
}

.nav-toggle {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    padding: var(--spacing-xs);
    color: var(--color-text);
}

.hamburger {
    display: flex;
    flex-direction: column;
    gap: 4px;
    width: 24px;
    height: 24px;
}

.hamburger span {
    width: 100%;
    height: 2px;
    background-color: currentColor;
    border-radius: 1px;
    transition: all var(--transition-normal);
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
}

.nav-menu a {
    display: block;
    padding: var(--spacing-sm) 0;
    color: var(--color-text);
    font-weight: 500;
    position: relative;
}

.nav-menu a::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-accent);
    transition: width var(--transition-fast);
}

.nav-menu a:hover::after,
.nav-menu a:focus::after {
    width: 100%;
}

@media (max-width: 768px) {
    .nav-toggle {
        display: flex;
        align-items: center;
        justify-content: center;
        order: 1;
    }

    .nav-menu {
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        flex-direction: column;
        gap: 0;
        background-color: var(--color-surface);
        border-bottom: 1px solid var(--color-border);
        padding: var(--spacing-md);
        display: none;
        box-shadow: var(--shadow-md);
    }

    .nav-menu.active {
        display: flex;
    }

    .nav-toggle[aria-expanded="true"] .hamburger span:nth-child(1) {
        transform: rotate(45deg) translate(8px, 8px);
    }

    .nav-toggle[aria-expanded="true"] .hamburger span:nth-child(2) {
        opacity: 0;
    }

    .nav-toggle[aria-expanded="true"] .hamburger span:nth-child(3) {
        transform: rotate(-45deg) translate(7px, -6px);
    }

    .logo {
        order: 0;
        flex: 1;
    }

    .header-actions {
        order: 2;
    }
}

/* ============================================
   HEADER ACTIONS
   ============================================ */

.header-actions {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    flex-shrink: 0;
}

.icon-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: var(--spacing-xs);
    color: var(--color-text);
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: var(--radius-md);
    transition: background-color var(--transition-fast);
    position: relative;
}

.icon-btn:hover {
    background-color: var(--color-border);
}

.icon-btn:focus {
    outline: 2px solid var(--color-secondary);
    outline-offset: 2px;
}

.icon-btn svg {
    width: 24px;
    height: 24px;
}

.cart-count {
    position: absolute;
    top: -4px;
    right: -4px;
    background-color: var(--color-secondary);
    color: var(--color-surface);
    font-size: 0.75rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 20px;
    text-align: center;
}

/* ============================================
   BUTTONS
   ============================================ */

.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--spacing-xs);
    padding: var(--spacing-sm) var(--spacing-lg);
    font-size: var(--font-size-base);
    font-weight: 600;
    border: 2px solid transparent;
    border-radius: var(--radius-md);
    cursor: pointer;
    transition: all var(--transition-fast);
    text-decoration: none;
    white-space: nowrap;
}

.btn:focus {
    outline: 2px solid var(--color-secondary);
    outline-offset: 2px;
}

.btn-primary {
    background-color: var(--color-secondary);
    color: var(--color-surface);
    border-color: var(--color-secondary);
}

.btn-primary:hover {
    background-color: #c0392b;
    border-color: #c0392b;
}

.btn-secondary {
    background-color: transparent;
    color: var(--color-secondary);
    border-color: var(--color-secondary);
}

.btn-secondary:hover {
    background-color: var(--color-secondary);
    color: var(--color-surface);
}

.btn-small {
    padding: var(--spacing-xs) var(--spacing-md);
    font-size: 0.875rem;
    font-weight: 500;
}

/* ============================================
   HERO SECTION
   ============================================ */

.hero {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-2xl);
    align-items: center;
    padding: var(--spacing-2xl) var(--spacing-md);
    background: linear-gradient(135deg, #fafaf8 0%, #f5ebe0 100%);
}

.hero-content {
    padding: var(--spacing-lg) 0;
}

.hero-content h1 {
    color: var(--color-primary);
}

.hero-content p {
    font-size: var(--font-size-lg);
    color: var(--color-text-light);
    margin-bottom: var(--spacing-lg);
}

.hero-image {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 400px;
}

.hero-placeholder {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, #d4a574 0%, #c9a87a 100%);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-lg);
}

@media (max-width: 768px) {
    .hero {
        grid-template-columns: 1fr;
        gap: var(--spacing-lg);
        padding: var(--spacing-xl) var(--spacing-md);
    }

    .hero-placeholder {
        min-height: 250px;
    }
}

/* ============================================
   SECTION LAYOUT
   ============================================ */

section {
    padding: var(--spacing-2xl) var(--spacing-md);
}

.section-header {
    text-align: center;
    margin-bottom: var(--spacing-2xl);
}

.section-header h2 {
    margin-bottom: var(--spacing-md);
}

.section-description {
    font-size: var(--font-size-lg);
    color: var(--color-text-light);
    max-width: 600px;
    margin: 0 auto;
}

.section-footer {
    text-align: center;
    margin-top: var(--spacing-2xl);
}

/* ============================================
   FEATURED PRODUCTS GRID
   ============================================ */

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-2xl);
}

.product-card {
    background-color: var(--color-surface);
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-md);
    transition: all var(--transition-normal);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.product-image {
    width: 100%;
    aspect-ratio: 1 / 1;
    object-fit: cover;
    background-color: var(--color-border);
}

.product-info {
    padding: var(--spacing-md);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.product-category {
    font-size: 0.875rem;
    color: var(--color-text-light);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: var(--spacing-xs);
}

.product-name {
    font-size: var(--font-size-lg);
    font-weight: 600;
    margin-bottom: var(--spacing-xs);
    color: var(--color-primary);
}

.product-price {
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: var(--color-secondary);
    margin-bottom: var(--spacing-md);
    margin-top: auto;
}

.product-button {
    width: 100%;
}

/* ============================================
   DEALS SECTION
   ============================================ */

.deals-section {
    background-color: var(--color-surface);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
}

.deal-card {
    position: relative;
    background-color: var(--color-background);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: all var(--transition-normal);
}

.deal-card:hover {
    box-shadow: var(--shadow-lg);
}

.deal-badge {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background-color: var(--color-secondary);
    color: var(--color-surface);
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: var(--radius-md);
    font-weight: 700;
    font-size: 0.875rem;
    z-index: 10;
}

.deal-card img {
    width: 100%;
    height: 250px;
    object-fit: cover;
    display: block;
}

.deal-card h3 {
    padding: var(--spacing-md) var(--spacing-md) var(--spacing-xs);
    margin: 0;
}

.original-price {
    padding: 0 var(--spacing-md);
    font-size: 0.875rem;
    color: var(--color-text-light);
    text-decoration: line-through;
    margin: 0;
}

.deal-price {
    padding: var(--spacing-xs) var(--spacing-md);
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: var(--color-secondary);
    margin: 0 0 var(--spacing-md) 0;
}

.deal-card .btn {
    margin: 0 var(--spacing-md) var(--spacing-md);
    width: calc(100% - 2 * var(--spacing-md));
}

/* ============================================
   EDITORIAL SECTION
   ============================================ */

.editorial-section {
    background: linear-gradient(135deg, #fafaf8 0%, #f5ebe0 100%);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: var(--spacing-lg);
}

.editorial-card {
    background-color: var(--color-surface);
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-md);
    transition: all var(--transition-normal);
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.editorial-card img {
    width: 100%;
    height: 200px;
    object-fit: cover;
    display: block;
}

.editorial-content {
    padding: var(--spacing-lg);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.article-date {
    font-size: 0.875rem;
    color: var(--color-text-light);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: var(--spacing-sm);
}

.editorial-card h3 {
    margin-bottom: var(--spacing-md);
}

.article-link {
    color: var(--color-primary);
}

.article-link:hover {
    color: var(--color-secondary);
}

.editorial-card p {
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
    flex: 1;
}

.read-more {
    font-weight: 600;
    color: var(--color-secondary);
    display: inline-block;
    position: relative;
}

.read-more::after {
    content: ' →';
    transition: transform var(--transition-fast);
}

.read-more:hover::after {
    transform: translateX(4px);
}

/* ============================================
   NEWSLETTER SECTION
   ============================================ */

.newsletter-section {
    background-color: var(--color-primary);
    color: var(--color-surface);
    text-align: center;
}

.newsletter-section h2 {
    color: var(--color-surface);
    margin-bottom: var(--spacing-md);
}

.newsletter-section p {
    font-size: var(--font-size-lg);
    color: rgba(255, 255, 255, 0.8);
    margin-bottom: var(--spacing-lg);
}

.newsletter-form {
    max-width: 500px;
    margin: 0 auto;
}

.form-group {
    display: flex;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-md);
}

.form-group input {
    flex: 1;
    min-width: 0;
    padding: var(--spacing-sm) var(--spacing-md);
    border: 2px solid var(--color-surface);
    border-radius: var(--radius-md);
    font-size: var(--font-size-base);
    font-family: inherit;
}

.form-group input:focus {
    outline: none;
    border-color: var(--color-accent);
    box-shadow: 0 0 0 3px rgba(212, 165, 116, 0.1);
}

.form-group input::placeholder {
    color: rgba(44, 62, 80, 0.5);
}

.form-group .btn {
    flex-shrink: 0;
}

.form-message {
    min-height: 24px;
    font-size: 0.875rem;
    font-weight: 500;
}

.form-message.success {
    color: var(--color-success);
}

.form-message.error {
    color: #e74c3c;
}

@media (max-width: 640px) {
    .form-group {
        flex-direction: column;
    }

    .form-group input {
        width: 100%;
    }

    .form-group .btn {
        width: 100%;
    }
}

/* ============================================
   ABOUT SECTION
   ============================================ */

.about-section {
    background-color: var(--color-surface);
}

.about-content {
    max-width: 700px;
    margin: 0 auto;
    text-align: center;
    font-size: var(--font-size-lg);
    color: var(--color-text-light);
}

.about-content p {
    margin-bottom: var(--spacing-lg);
}

/* ============================================
   FOOTER
   ============================================ */

footer {
    background-color: var(--color-primary);
    color: var(--color-surface);
    padding: var(--spacing-2xl) var(--spacing-md);
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-2xl);
}

.footer-section h3 {
    color: var(--color-surface);
    margin-bottom: var(--spacing-md);
    font-size: var(--font-size-lg);
}

.footer-section ul {
    list-style: none;
}

.footer-section a {
    color: rgba(255, 255, 255, 0.8);
    display: block;
    padding: var(--spacing-xs) 0;
    transition: color var(--transition-fast);
}

.footer-section a:hover {
    color: var(--color-accent);
    text-decoration: none;
}

.footer-bottom {
    padding-top: var(--spacing-lg);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--spacing-lg);
    font-size: 0.875rem;
    color: rgba(255, 255, 255, 0.7);
}

.footer-links {
    display: flex;
    gap: var(--spacing-lg);
}

.footer-links a {
    color: rgba(255, 255, 255, 0.7);
}

.footer-links a:hover {
    color: var(--color-accent);
}

@media (max-width: 768px) {
    .footer-bottom {
        justify-content: center;
        text-align: center;
    }
}

/* ============================================
   FORCED COLORS & HIGH CONTRAST
   ============================================ */

@media (forced-colors: active) {
    .btn-primary {
        forced-color-adjust: none;
        border: 2px solid ButtonText;
        background-color: ButtonFace;
        color: ButtonText;
    }

    .btn-primary:hover {
        background-color: Highlight;
        color: HighlightText;
    }

    .deal-badge,
    .cart-count {
        forced-color-adjust: none;
        border: 1px solid CurrentColor;
    }

    a {
        forced-color-adjust: none;
        text-decoration: underline;
    }

    a:focus {
        outline: 2px solid;
    }
}

/* ============================================
   RESPONSIVE DESIGN
   ============================================ */

@media (max-width: 1024px) {
    :root {
        --font-size-3xl: 2rem;
        --font-size-2xl: 1.5rem;
        --spacing-2xl: 2.5rem;
    }
}

@media (max-width: 640px) {
    :root {
        --spacing-lg: 1.5rem;
        --spacing-xl: 2rem;
        --font-size-lg: 1rem;
        --font-size-2xl: 1.5rem;
    }

    h1 {
        font-size: var(--font-size-2xl);
    }

    section {
        padding: var(--spacing-lg) var(--spacing-md);
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
        gap: var(--spacing-md);
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }
}

/* ============================================
   FOCUS VISIBLE STATE
   ============================================ */

button:focus-visible,
a:focus-visible,
input:focus-visible {
    outline: 2px solid var(--color-secondary);
    outline-offset: 2px;
}

