        display: inline;
    }
}

/* ============================================
   NAVIGATION
   ============================================ */

.main-nav {
    flex: 1;
    min-width: 0;
}

.nav-toggle {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    padding: var(--spacing-xs);
    color: var(--color-text);
}

.hamburger {
    display: flex;
    flex-direction: column;
    gap: 4px;
    width: 24px;
    height: 24px;
}

.hamburger span {
    width: 100%;
    height: 2px;
    background-color: currentColor;
    border-radius: 1px;
    transition: all var(--transition-normal);
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
}

.nav-menu a {
    display: block;
    padding: var(--spacing-sm) 0;
    color: var(--color-text);
    font-weight: 500;
    position: relative;
}

.nav-menu a::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-accent);
    transition: width var(--transition-fast);
}

.nav-menu a:hover::after,
.nav-menu a:focus::after {
    width: 100%;
}

@media (max-width: 768px) {
