+// ============================================
+// SEARCH BUTTON
+// ============================================
+
+function setupSearch() {
+    const searchBtn = document.querySelector('.search-btn');
+    if (!searchBtn) return;
+
+    searchBtn.addEventListener('click', () => {
+        const query = prompt('What are you looking for?');
+        if (query) {
+            alert(`Searching for: "${query}"\n\nThis would search your products.`);
+        }
+    });
+}
+
+// ============================================
+// INTERSECTION OBSERVER FOR ANIMATIONS
+// ============================================
+
+function setupIntersectionObserver() {
+    const observerOptions = {
+        threshold: 0.1,
+        rootMargin: '0px 0px -50px 0px'
+    };
+
+    const observer = new IntersectionObserver((entries) => {
+        entries.forEach(entry => {
+            if (entry.isIntersecting) {
+                entry.target.style.opacity = '1';
+                entry.target.style.transform = 'translateY(0)';
+            }
+        });
+    }, observerOptions);
+
+    // Observe product cards
+    document.querySelectorAll('.product-card, .deal-card, .editorial-card').forEach(card => {
+        card.style.opacity = '0';
+        card.style.transform = 'translateY(20px)';
+        card.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
+        observer.observe(card);
+    });
+}
+
+// ============================================
+// KEYBOARD NAVIGATION
+// ============================================
+
+function setupKeyboardNavigation() {
+    document.addEventListener('keydown', (e) => {
+        // Alt + S to focus search
+        if (e.altKey && e.key === 's') {
+            e.preventDefault();
+            document.querySelector('.search-btn')?.focus();
+        }
+
+        // Alt + C to focus cart
+        if (e.altKey && e.key === 'c') {
+            e.preventDefault();
+            document.getElementById('cart-btn')?.focus();
+        }
+    });
+}
+
+// ============================================
+// INITIALIZE
+// ============================================
+
+document.addEventListener('DOMContentLoaded', () => {
+    renderFeaturedProducts();
+    setupMobileNav();
+    setupNewsletter();
+    setupCartButton();
+    setupHeroCTA();
+    setupSmoothScroll();
+    setupSearch();
+    setupIntersectionObserver();
+    setupKeyboardNavigation();
+});
+
')
